   104→/// TC-INP-002: Verify camera extrinsic parameters (pose) are correctly parsed from COLMAP.
   105→///
   106→/// Pass Criteria:
   107→/// - Rotation error < 0.1 degrees
   108→/// - Translation error < 0.001 units
   109→/// - All rotation matrices satisfy R^T * R = I within 1e-6
   110→#[test]
   111→fn tc_inp_002_camera_extrinsics_parsing() {
   112→    use nalgebra::Matrix3;
   113→
   114→    // Use a known dataset
   115→    let dataset_path = PathBuf::from("datasets/garden/sparse/0");
   116→
   117→    if !dataset_path.exists() {
   118→        eprintln!("Skipping test - dataset not found at {:?}", dataset_path);
   119→        eprintln!("Run setup to download datasets first");
   120→        return;
   121→    }
   122→
   123→    // Load the scene
   124→    let scene = load_colmap_scene(&dataset_path)
   125→        .expect("Failed to load COLMAP scene");
   126→
   127→    assert!(scene.images.len() > 0, "No images loaded");
   128→
   129→    // Test extrinsics parsing by validating:
   130→    // 1. Rotation quaternions are valid (unit quaternions)
   131→    // 2. Rotation matrices are orthonormal (R^T * R = I)
   132→    // 3. Values maintain precision (not truncated)
   133→
   134→    let mut num_valid = 0;
   135→
   136→    for image_info in scene.images.iter() {
   137→        println!("Image {}: {}", image_info.id, image_info.name);
   138→
   139→        // Extract quaternion components
   140→        let quat = image_info.rotation;
   141→        let qw = quat.w;
   142→        let qx = quat.i;
   143→        let qy = quat.j;
   144→        let qz = quat.k;
   145→
   146→        println!("  Quaternion: w={:.6}, x={:.6}, y={:.6}, z={:.6}", qw, qx, qy, qz);
   147→        println!("  Translation: x={:.6}, y={:.6}, z={:.6}",
   148→            image_info.translation.x, image_info.translation.y, image_info.translation.z);
   149→
   150→        // Verify quaternion is normalized (should be unit quaternion)
   151→        let quat_norm = (qw * qw + qx * qx + qy * qy + qz * qz).sqrt();
   152→        assert!((quat_norm - 1.0).abs() < 1e-6,
   153→            "Image {} quaternion not normalized: norm={}", image_info.id, quat_norm);
   154→
   155→        // Convert quaternion to rotation matrix
   156→        let rotation_matrix: Matrix3<f32> = quat.to_rotation_matrix().into_inner();
   157→
   158→        // Verify rotation matrix is orthonormal: R^T * R = I
   159→        let rt_r: Matrix3<f32> = rotation_matrix.transpose() * rotation_matrix;
   160→        let identity: Matrix3<f32> = Matrix3::identity();
   161→
   162→        for i in 0..3 {
   163→            for j in 0..3 {
   164→                let diff = (rt_r[(i, j)] - identity[(i, j)]).abs();
   165→                assert!(diff < 1e-6,
   166→                    "Image {} rotation matrix not orthonormal at ({},{}): R^T*R - I = {}",
   167→                    image_info.id, i, j, diff);
   168→            }
   169→        }
   170→
   171→        // Verify determinant is +1 (proper rotation, not reflection)
   172→        let det = rotation_matrix.determinant();
   173→        assert!((det - 1.0).abs() < 1e-6,
   174→            "Image {} rotation matrix determinant != 1: det={}", image_info.id, det);
   175→
   176→        // Verify precision is maintained (values should have fractional parts)
   177→        // At least some rotation or translation components should not be exact integers
   178→        let has_rotation_precision =
   179→            qx.fract().abs() > 0.001 || qy.fract().abs() > 0.001 ||
   180→            qz.fract().abs() > 0.001 || qw.fract().abs() > 0.001;
   181→        let has_translation_precision =
   182→            image_info.translation.x.fract().abs() > 0.001 ||
   183→            image_info.translation.y.fract().abs() > 0.001 ||
   184→            image_info.translation.z.fract().abs() > 0.001;
   185→
   186→        if !has_rotation_precision && !has_translation_precision {
   187→            eprintln!("Warning: Image {} has suspiciously round pose values - may be synthetic",
   188→                image_info.id);
   189→        }
   190→
   191→        num_valid += 1;
   192→    }
   193→
   194→    println!("\n✅ TC-INP-002: Camera extrinsics parsing validated");
   195→    println!("   {} images with valid camera poses", num_valid);
   196→    println!("   All rotation matrices are orthonormal (R^T * R = I within 1e-6)");
   197→    println!("   All quaternions are properly normalized");
   198→}
