   861→/// Helper function to verify matrix is symmetric
   862→fn verify_symmetric(matrix: &Matrix3<f32>, tolerance: f32, test_name: &str) {
   863→    for i in 0..3 {
   864→        for j in 0..3 {
   865→            let diff = (matrix[(i, j)] - matrix[(j, i)]).abs();
   866→            assert!(diff < tolerance,
   867→                "{}: Matrix not symmetric at ({},{}): {} vs {}",
   868→                test_name, i, j, matrix[(i, j)], matrix[(j, i)]);
   869→        }
   870→    }
   871→}
   872→
   873→/// Helper function to verify matrix is positive semi-definite
   874→/// (all eigenvalues >= 0)
   875→fn verify_positive_semidefinite(matrix: &Matrix3<f32>, test_name: &str) {
   876→    // Compute eigenvalues
   877→    let eigen = matrix.symmetric_eigen();
   878→    let eigenvalues = eigen.eigenvalues;
   879→
   880→    println!("  Eigenvalues: ({:.6}, {:.6}, {:.6})",
   881→        eigenvalues[0], eigenvalues[1], eigenvalues[2]);
   882→
   883→    for (i, &eigenvalue) in eigenvalues.iter().enumerate() {
   884→        assert!(eigenvalue >= -1e-6,
   885→            "{}: Negative eigenvalue {} at index {}: {}",
   886→            test_name, i, i, eigenvalue);
   887→    }
   888→}
