   890→/// TC-SH-001: Verify SH degree 0 produces view-independent color.
   891→///
   892→/// Pass Criteria:
   893→/// - Maximum color deviation across all views < 1e-6
   894→/// - RGB values match expected DC color
   895→#[test]
   896→fn tc_sh_001_degree_0_view_independence() {
   897→    use sugar_rs::core::{evaluate_sh, SH_C0};
   898→    use nalgebra::Vector3;
   899→
   900→    const TOLERANCE: f32 = 1e-6;
   901→
   902→    println!("\n=== TC-SH-001: SH Degree 0 (DC) View Independence ===\n");
   903→
   904→    // Test with several different DC coefficient values
   905→    let test_cases = vec![
   906→        ([1.0, 0.5, 0.2], "bright red-orange"),
   907→        ([0.0, 0.0, 0.0], "mid gray (zero coeffs)"),
   908→        ([-1.0, -1.0, -1.0], "dark (negative coeffs)"),
   909→        ([0.5, 1.0, -0.3], "greenish"),
   910→    ];
   911→
   912→    for (dc_coeffs, description) in test_cases {
   913→        println!("Test case: {}", description);
   914→        println!("  DC coefficients: ({:.3}, {:.3}, {:.3})", dc_coeffs[0], dc_coeffs[1], dc_coeffs[2]);
   915→
   916→        // Create SH coefficient array with only degree 0 (DC) set
   917→        let mut sh_coeffs = [[0.0f32; 3]; 16];
   918→        sh_coeffs[0] = dc_coeffs;
   919→
   920→        // Expected color from DC component only
   921→        // Formula: color = sh_coeffs[0] * SH_C0
   922→        // (The 0.5 offset is only in evaluate_sh_dc_only, not in evaluate_sh)
   923→        let expected_color = Vector3::new(
   924→            (dc_coeffs[0] * SH_C0).clamp(0.0, 1.0),
   925→            (dc_coeffs[1] * SH_C0).clamp(0.0, 1.0),
   926→            (dc_coeffs[2] * SH_C0).clamp(0.0, 1.0),
   927→        );
   928→
   929→        println!("  Expected color: ({:.6}, {:.6}, {:.6})",
   930→            expected_color.x, expected_color.y, expected_color.z);
   931→
   932→        // Test from multiple viewing directions
   933→        let test_directions = vec![
   934→            Vector3::new(1.0, 0.0, 0.0),    // +X
   935→            Vector3::new(-1.0, 0.0, 0.0),   // -X
   936→            Vector3::new(0.0, 1.0, 0.0),    // +Y
   937→            Vector3::new(0.0, -1.0, 0.0),   // -Y
   938→            Vector3::new(0.0, 0.0, 1.0),    // +Z
   939→            Vector3::new(0.0, 0.0, -1.0),   // -Z
   940→            Vector3::new(1.0, 1.0, 1.0).normalize(),     // Diagonal
   941→            Vector3::new(0.5, -0.3, 0.8).normalize(),    // Random 1
   942→            Vector3::new(-0.7, 0.6, -0.4).normalize(),   // Random 2
   943→        ];
   944→
   945→        let mut max_deviation = 0.0f32;
   946→        let mut max_deviation_dir = Vector3::zeros();
   947→
   948→        for direction in &test_directions {
   949→            let color = evaluate_sh(&sh_coeffs, direction);
   950→
   951→            // Compute deviation from expected color
   952→            let deviation = (color - expected_color).norm();
   953→
   954→            if deviation > max_deviation {
   955→                max_deviation = deviation;
   956→                max_deviation_dir = *direction;
   957→            }
   958→
   959→            // Verify each channel matches within tolerance
   960→            assert!((color.x - expected_color.x).abs() < TOLERANCE,
   961→                "Red channel varies with view direction: {} vs {} (dir: {:?})",
   962→                color.x, expected_color.x, direction);
   963→            assert!((color.y - expected_color.y).abs() < TOLERANCE,
   964→                "Green channel varies with view direction: {} vs {} (dir: {:?})",
   965→                color.y, expected_color.y, direction);
   966→            assert!((color.z - expected_color.z).abs() < TOLERANCE,
   967→                "Blue channel varies with view direction: {} vs {} (dir: {:?})",
   968→                color.z, expected_color.z, direction);
   969→        }
   970→
   971→        println!("  Maximum deviation across {} views: {:.6} (requirement: < 1e-6)",
   972→            test_directions.len(), max_deviation);
   973→        println!("  Maximum deviation occurred at direction: ({:.3}, {:.3}, {:.3})",
   974→            max_deviation_dir.x, max_deviation_dir.y, max_deviation_dir.z);
   975→
   976→        assert!(max_deviation < TOLERANCE,
